import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average of the last 80 closing prices
    sma_80 = df['close'].rolling(window=80).mean()

    # Initialize the target positions series with 0
    signals = pd.Series(0, index=df.index)

    # Loop through each bar to decide the position
    for i in range(len(df)):
        if df.index[i] == df.index[0] or len(sma_80) > 79:
            # Ensure there are enough data points for the SMA(80)
            if sma_80[i] is not np.nan:
                # Apply the trading rule
                if df['close'].iloc[i] > sma_80.iloc[i]:
                    signals.iloc[i] = 1
                else:
                    signals.iloc[i] = 0
            else:
                # Warm-up period
                signals.iloc[i] = 0
        else:
            # No signal during warm-up
            signals.iloc[i] = 0

    return signals
