    ema_20 = df['close'].ewm(span=20, adjust=False).mean()
    ema_100 = df['close'].ewm(span=100, adjust=False).mean()

    # Initialize the signals as flat (0) for warm-up
    signals = np.zeros(len(df), dtype=int)

    for i in range(len(df)):
