    # Ensure that we have sufficient data for the SMA(5) calculation
    warm_up_length = 4
    if len(df) < warm_up_length:
        return pd.Series(0, index=df.index)

    # Calculate the SMA(5) for each bar
    sma_5 = df['close'].rolling(window=5).mean()

    # Initialize the signals series with flat positions
    signals = pd.Series(0, index=df.index)

    # Determine the signals
    for i in range(warm_up_length, len(df)):
        if df.at[df.index[i], 'close'] > sma_5.at[df.index[i]]:
            signals.at[df.index[i]] = 1
        elif df.at[df.index[i], 'close'] < sma_5.at[df.index[i]]:
            signals.at[df.index[i]] = -1

    return signals
