    ema_55 = df['close'].ewm(span=55, adjust=False).mean()

    # Initialize signals as flat (0)
    signals = np.zeros_like(df.index, dtype=int)

    # Decide on signals
    for i in range(len(df)):
        if i >= 54:  # Ensure we have enough data for EMA(55)
            if ema_10[i] > ema_55[i]:
                signals[i] = 1
            elif ema_10[i] < ema_55[i]:
                signals[i] = -1

    return pd.Series(signals, index=df.index)
