import numpy as np
import pandas as pd
import math

def generate_signals(df: pd.DataFrame) -> pd.Series:
    def ema(series, n):
        alpha = 2 / (n + 1)
        ema_series = pd.Series(0, index=series.index)
        ema_series.iloc[0] = series.iloc[0]
        for i in range(1, len(series)):
            ema_series.iloc[i] = alpha * series.iloc[i] + (1 - alpha) * ema_series.iloc[i - 1]
        return ema_series

    ema20 = ema(df['close'], 20)
    ema110 = ema(df['close'], 110)

    signals = pd.Series(0, index=ema20.index)
    for i in range(len(df)):
        if i >= 109:
            if ema20.iloc[i] > ema110.iloc[i]:
                signals.iloc[i] = 1
            elif ema20.iloc[i] < ema110.iloc[i]:
                signals.iloc[i] = -1

    return signals
