def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average (SMA) of the last 90 closing prices
    sma_90 = df['close'].rolling(window=90).mean().fillna(0)

    # Initialize the target signals as zeros (flat)
    signals = np.zeros(len(df), dtype=int)

    # Determine the signals based on the condition (close > SMA or close < SMA)
    for i in range(len(df)):
        if i >= 89:  # Ensure we have enough data for the SMA(90)
            if df['close'].iloc[i] > sma_90.iloc[i]:
                signals[i] = 1  # Long position
            elif df['close'].iloc[i] < sma_90.iloc[i]:
                signals[i] = -1  # Short position

    return pd.Series(signals, index=df.index)
