import numpy as np

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the RSI for the first bar
    df['RSI_10'] = df['close'].pct_change().rolling(window=10).mean()

    # Initialize the position series with 0
    position = pd.Series(0, index=df.index)

    # Generate the position series
    for i in range(len(df)):
        if position.iat[i-1] == 0:
            # Flat, go long when RSI(10) < 10
            if df['RSI_10'].iat[i] < 10:
                position.iat[i] = 1
        elif position.iat[i-1] == 1:
            # Long, exit to flat when RSI(10) > 60
            if df['RSI_10'].iat[i] > 60:
                position.iat[i] = 0

    return position
