import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average (SMA) of the RSI(7)
    sma_rsi_7 = df['close'].pct_change().rolling(window=7).mean()

    # Initialize the position series with flat (0)
    position = pd.Series(0, index=df.index)

    # Iterate over each bar to update the position
    for i in range(len(df)):
        if i < 6:
            # Warm-up period: no position
            position.iloc[i] = 0
        else:
            if position.iloc[i-1] == 0:
                # Flat, go long when RSI(7) < 32
                if sma_rsi_7.iloc[i] < 32:
                    position.iloc[i] = 1
                else:
                    position.iloc[i] = position.iloc[i-1]
            elif position.iloc[i-1] == 1:
                # Long, exit to flat when RSI(7) > 40
                if sma_rsi_7.iloc[i] > 40:
                    position.iloc[i] = 0
                else:
                    position.iloc[i] = position.iloc[i-1]
            else:
                # Keep the current position otherwise
                position.iloc[i] = position.iloc[i-1]

    return position
