import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the target positions
    signals = np.zeros(len(df), dtype=int)

    # Warm-up period
    warm_up_length = 10
    for i in range(warm_up_length):
        if df['HH'][i] == df['LL'][i]:
            continue
        k = 100 * (df['close'][i] - df['LL'][i]) / (df['HH'][i] - df['LL'][i])
        if k < 15:
            signals[i] = 1
        elif k > 48:
            signals[i] = 0

    # Trading logic
    for i in range(warm_up_length, len(df)):
        k = 100 * (df['close'][i] - df['LL'][i]) / (df['HH'][i] - df['LL'][i])

        if signals[i-1] == 0:
            if k < 15:
                signals[i] = 1
        elif signals[i-1] == 1:
            if k > 48:
                signals[i] = 0
        else:
            signals[i] = signals[i-1]

    return pd.Series(signals, index=df.index)

