import numpy as np
import pandas as pd
from pandas.core.indexes.datetimes import DatetimeIndex
from pandas.core.indexes.base import Index

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate %K(15)
    hh = df['high'].rolling(window=15).max()
    ll = df['low'].rolling(window=15).min()
    k = 100 * (df['close'] - ll) / (hh - ll)
    k[k.isnull()] = 50

    # Initialize signals with flat positions
    signals = np.zeros(len(df), dtype=int)

    # Apply rules for long and flat positions
    for i in range(len(df)):
        if df.index[i] == df.index[0] or len(df.index) <= 14:
            continue  # Warm-up period: no signal

        if signals[i-1] == 0:
            if k[i] < 32:
                signals[i] = 1
        elif signals[i-1] == 1:
            if k[i] > 40:
                signals[i] = 0

    return pd.Series(signals, index=df.index)
