def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialization
    rsi_30 = df['close'].pct_change().rolling(window=30).mean()
    rsi_30 = rsi_30.interpolate(method='linear')  # Interpolate for warm-up period
    rsi_30 = rsi_30.fillna(55)  # Fill warm-up period with a flat position

    # Signal generation logic
    signals = np.zeros(len(df), dtype=int)
    for i in range(len(rsi_30)):
        if i < 29:
            signals[i] = 0  # Warm-up period
        elif rsi_30[i] < 32:
            signals[i] = 1  # Go long
        elif rsi_30[i] > 68:
            signals[i] = -1  # Go short
        elif rsi_30[i] > 55:
            signals[i] = 0  # Exit to flat

    return pd.Series(signals, index=df.index)
