import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Warm-up period
    warm_up_periods = 14
    if len(df) < warm_up_periods:
        return pd.Series(0, index=df.index)

    # Calculate %K(15)
    def stochastic_k(close, high, low, n=15):
        hh = high.rolling(window=n).max()
        ll = low.rolling(window=n).min()
        k = 100 * (close - ll) / (hh - ll)
        k[k.isnull()] = 50
        return k

    k = stochastic_k(df['close'], df['high'], df['low'])

    # Initialize the signals series
    signals = pd.Series(0, index=df.index)

    # Iterate over each bar to set the signal
    for i in range(warm_up_periods, len(df)):
        if signals.at[df.index[i-1]] == 0:
            # Flat, go long when %K(15) < 22
            if k.at[df.index[i]] < 22:
                signals.at[df.index[i]] = 1
        elif signals.at[df.index[i-1]] == 1:
            # Long, exit to flat when %K(15) > 48
            if k.at[df.index[i]] > 48:
                signals.at[df.index[i]] = 0

    return signals
