    # Loop through each bar to generate signals
    for i in range(25, len(df)):
        if df.loc[df.index[i], 'close'] > get_prior_bar(i, 25):
            signals.loc[df.index[i]] = 1
        elif df.loc[df.index[i], 'close'] < get_prior_bar(i, 25):
            signals.loc[df.index[i]] = -1

    return signals
