import pandas as pd
import numpy as np

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the 25-bar high and 6-bar low for each bar
    df['25_high'] = df['high'].rolling(window=25).max()
    df['6_low'] = df['low'].rolling(window=6).min()

    # Initialize the signals series
    signals = pd.Series(0, index=df.index)

    # Warm-up period
    warm_up_periods = 25
    for i in range(warm_up_periods - 1):
        if df['close'].iloc[i] > df['25_high'].iloc[i]:
            signals.iloc[i] = 1
        elif df['close'].iloc[i] < df['6_low'].iloc[i]:
            signals.iloc[i] = -1

    # Main trading logic
    for i in range(warm_up_periods, len(df)):
        if df['close'].iloc[i] > df['25_high'].iloc[i]:
            signals.iloc[i] = 1
        elif df['close'].iloc[i] < df['6_low'].iloc[i]:
            signals.iloc[i] = -1
        # Exit from flat to long/short
        elif signals.iloc[i-1] == 0 and df['close'].iloc[i] < df['6_low'].iloc[i]:
            signals.iloc[i] = signals.iloc[i] * -1
        elif signals.iloc[i-1] == 0 and df['close'].iloc[i] > df['25_high'].iloc[i]:
            signals.iloc[i] = signals.iloc[i] * -1

    return signals
