import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Warm-up period
    if df.index[0] == 0:
        return pd.Series(0, index=df.index)

    # Helper function to calculate the prior N-bar high or low
    def prior_n_bar(data: pd.Series, n: int) -> pd.Series:
        return data.rolling(window=n).max() if n > 0 else pd.Series(0, index=data.index)

    # Prior 15-bar high and low
    df['prior_15_high'] = prior_n_bar(df['high'], 15)
    df['prior_15_low'] = prior_n_bar(df['low'], 15)
    df['prior_5_high'] = prior_n_bar(df['high'], 5)
    df['prior_5_low'] = prior_n_bar(df['low'], 5)

    # Initialize the signals series
    signals = pd.Series(0, index=df.index)

    # Generate the signals
    for i in range(len(df)):
        if i < 14:
            # Warm-up period
            signals[i] = 0
        else:
            # Apply the strategy
            if df['close'].iloc[i] > df['prior_15_high'].iloc[i]:
                signals[i] = 1
            elif df['close'].iloc[i] < df['prior_15_low'].iloc[i]:
                signals[i] = -1

    return signals
