    rolling_low = df['low'].rolling(window=35).min()

    # Generate signals
    signals = pd.Series(index=df.index, dtype=int)
    for t in range(len(df)):
        if position == 0:
            # Flat
            if df['close'].iloc[t] > rolling_high.iloc[t-1]:
                position = 1
            elif df['close'].iloc[t] < rolling_low.iloc[t-1]:
                position = -1
        else:
            # Long/Short
            if df['close'].iloc[t] < rolling_low.iloc[t-1]:
                position = 0
            elif df['close'].iloc[t] > rolling_high.iloc[t-1]:
                position = 0

        signals.iloc[t] = position

    return signals
