def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Warm-up period
    if df.index[0] == 0:
        return pd.Series(0, index=df.index, dtype=int)

    # Initialize the signals series
    signals = pd.Series(0, index=df.index, dtype=int)

    # Get the prior 10-bar highest and lowest
    def get_prior_10(data, i):
        return data[i-10:i].max(), data[i-10:i].min()

    # Loop through the DataFrame
    for i in range(10, len(df)):
        prior_10_highest, prior_10_lowest = get_prior_10(df['close'], i)

        # Apply the strategy
        if df['close'].iloc[i] > prior_10_highest:
            signals.iloc[i] = 1
        elif df['close'].iloc[i] < prior_10_lowest:
            signals.iloc[i] = 0

    return signals
