            # On first bar, go long when close > prior 45-bar highest close
            if close > prior_45_highest_close:
                return 1
            else:
                return 0
        else:
            # Exit to flat when close <= entry price * (1 - 0.03) (stop-loss)
            if close <= df['entry_price'].iloc[0] * (1 - 0.03):
                return 0
            # Enter to long when close > prior 45-bar highest close
            elif close > prior_45_highest_close:
                df['entry_price'].iloc[0] = close
                return 1
            # Exit to flat when close >= entry price * (1 + 0.07) (take-profit)
            elif close >= df['entry_price'].iloc[0] * (1 + 0.07):
                return 0
            # Stay long otherwise
            else:
                return df['position'].iloc[-1]

    # Initialize the position series
    positions = pd.Series(0, index=df.index)

    # Calculate the position for each bar
    for i in range(len(df)):
        positions.iloc[i] = calculate_position(df['close'].iloc[i], df['prior_45_highest_close'].iloc[i])

    return positions
