        elif exit:
            return 0
        else:
            return 0

    df['One_bar_return'] = one_bar_return(df['close'])
    df['Entry_signal'] = entry_signal(df['close'])
    df['Exit_signal'] = exit_signal(df['close'], df['Entry_signal'])

