import numpy as np
import pandas as pd
import math

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the signals series
    signals = pd.Series(0, index=df.index)

    # Calculate the RSI(9) for each bar
    def rsi(series, n=9):
        gains = series.diff().clip(lower=0)
        losses = series.diff().clip(upper=0)
        avg_gain = losses.rolling(window=n).mean()
        avg_loss = gains.rolling(window=n).mean()
        rsi_value = 100 - 100 / (1 + avg_gain / avg_loss)
        rsi_value[rsi_value.isnull()] = 100
        return rsi_value

    # Iterate over each bar to set the signals
    for i in range(len(df)):
        rsi_val = rsi(df['close'], 9)

        # Signal update logic
        if signals.iat[i-1] == 0:
            if rsi_val.iat[i] < 30 and signals.iat[i] == 0:
                signals.iat[i] = 1
            elif signals.iat[i] != 0:
                continue
        else:
            if rsi_val.iat[i] < 30 and signals.iat[i] == 1:
                signals.iat[i] = 2
            elif signals.iat[i] != 0:
                continue

        # Ensure signal is defined for the holding period
        if i < 11:
            continue

        # Finalize the signal for the holding period
        if signals.iat[i] == 1:
            signals.iat[i] = 3
        elif signals.iat[i] == 2:
            signals.iat[i] = 4

    return signals
