    sma_90 = df['close'].rolling(window=90).mean().fillna(method='ffill')

    # Calculate the relative strength index (RSI) of the last 5 closing prices
    rsi_5 = pd.DataFrame({
        'close_diff': df['close'].diff(),
        'gain': np.where(df['close_diff'] > 0, df['close_diff'], 0),
        'loss': np.where(df['close_diff'] < 0, -df['close_diff'], 0)
    })
    rsi_5['avg_gain'] = rsi_5['gain'].rolling(window=5).mean()
    rsi_5['avg_loss'] = rsi_5['loss'].rolling(window=5).mean()
    rsi_5['rsi'] = 100 - 100 / (1 + rsi_5['avg_gain'] / rsi_5['avg_loss'])

    # Initialize the position series
    position = pd.Series(0, index=df.index)

    # Iterate over each bar to generate position changes
    for i in range(len(df)):
        if i < 49:  # Warm-up period
            position.iloc[i] = 0
        else:
            if position.iloc[i-1] == 0:
                # Flat position
                if df['close'].iloc[i] > sma_90.iloc[i] and rsi_5['rsi'].iloc[i] < 30:
                    position.iloc[i] = 1
                elif df['close'].iloc[i] < sma_90.iloc[i] and rsi_5['rsi'].iloc[i] > 70:
                    position.iloc[i] = -1
            else:
                # Long/Short position
                if rsi_5['rsi'].iloc[i] > 75 or df['close'].iloc[i] < sma_90.iloc[i]:
                    position.iloc[i] = 0
                elif rsi_5['rsi'].iloc[i] < 25 or df['close'].iloc[i] > sma_90.iloc[i]:
                    position.iloc[i] = position.iloc[i]

    return position
