```python
import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    def sma(data: pd.Series, window: int) -> pd.Series:
        return data.rolling(window=window).mean()

    sma_90 = sma(df['close'], 90)
    sma_8 = sma(df['close'], 8)
    sma_35 = sma(df['close'], 35)

    signals = np.zeros(len(df), dtype=int)

    for t in range(len(df)):
        if t < 8:
            signals[t] = 0  # Warm-up period
        else:
            if df['close'].iloc[t] > sma_90.iloc[t] and sma_8.iloc[t] > sma_35.iloc[t]:
                signals[t] = 1  # Long
            elif df['close'].iloc[t] < sma_90.iloc[t] and sma_8.iloc[t] < sma_35.iloc[t]:
                signals[t] = -1  # Short

    return pd.Series(signals, index=df.index)

